// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        // The initial owner is address(0): it hands ownership to the fuzzed actor.
        vm.prank(address(0));
        c.transferOwnership(actor);
        assertEq(c.owner(), actor);
        // Rule: the current owner may transfer ownership to ANY address, including address(0).
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(address(0)) { ok = true; } catch { ok = false; }
        assertTrue(ok && c.owner() == address(0));
    }
}
